"""The audio of a sung Soft episode: lines and effects generated by the engine, a groove from the same beat grid.

ARCHITECTURAL REQUIREMENT: LLMs will always produce some form of error.
Absence of output verification is a design defect, not a runtime bug.
All LLM output must be treated as untrusted and validated explicitly.

Each line and effect is a ``<generated>`` item for the ``srstudio-elevenlabs`` provider, resolved and pinned
by the engine. Speech-to-text must hear every line as written, or the build stops. Lines are placed on the
:class:`~srstudio.music.Groove`; a line that does not end before the next one starts stops the build instead
of overlapping it. The groove is synthesised by :mod:`srstudio.music` from the same grid, so music, voices
and the poses share one tempo. :func:`main` writes ``dialogue.json`` for the episode script.
"""

from __future__ import annotations

import argparse
import json
import math
import os
import shutil
import sys
from collections.abc import Callable, Sequence
from dataclasses import dataclass, field
from pathlib import Path

from srstudio import fonts
from srstudio.generated import (
    Generated,
    PlacedClip,
    Placement,
    audio_document,
    gain_to_peak,
    pinned,
    resolve,
    trim_effect,
    trim_speech,
)
from srstudio.music import Groove, Section, render, write_wav
from srstudio.provider import CACHE_ENV, CONSENT_ENV, KEY_ENV, NAME, SFX_MODEL, format_voice
from srstudio.styles import SOFT
from srstudio.voice import MODEL, STT_MODEL, ElevenLabsClient, TranscriptMismatch, VoiceSettings, check_transcript

RATE = 48000
FPS = 30
TAIL = 0.4
MUSIC_PEAK, VOICE_PEAK = 0.34, 0.80


@dataclass(frozen=True)
class Voice:
    id: str
    name: str
    settings: dict[str, float] = field(default_factory=dict)


@dataclass(frozen=True)
class Line:
    role: str
    text: str  # what is spoken, and what speech-to-text must hear
    caption: str
    at: tuple[float, float]  # (bar, beat) it starts on
    speed: float = 1.0


@dataclass(frozen=True)
class Effect:
    id: str
    prompt: str
    seconds: float  # requested length
    longest: float  # kept after the onset
    peak: float
    at: tuple[float, float]
    early: float = 0.04  # starts this much before its beat, so the attack lands on it


@dataclass(frozen=True)
class Song:
    slug: str
    title: str
    seed: int
    groove: Groove
    voices: dict[str, Voice]  # by role
    lines: Sequence[Line]
    sections: Sequence[Section]
    effects: Sequence[Effect]
    lines_end: float  # (seconds) the last line must end before this
    voice_note: str


def declarations(song: Song) -> tuple[list[Generated], list[Generated]]:
    lines = [
        Generated(
            id=f"line-{i + 1}",
            kind="speech",
            provider=NAME,
            model=MODEL,
            prompt=line.text,
            voice=format_voice(
                song.voices[line.role].id, VoiceSettings(speed=line.speed, **song.voices[line.role].settings)
            ),
            language="en",
            seed=song.seed,
            cache=f"assets/generated/line-{i + 1}.wav",
            license="ElevenLabs output; premade voice " + song.voices[line.role].name,
        )
        for i, line in enumerate(song.lines)
    ]
    effects = [
        Generated(
            id=fx.id,
            kind="sound-effect",
            provider=NAME,
            model=SFX_MODEL,
            prompt=fx.prompt,
            duration=fx.seconds,
            cache=f"assets/generated/{fx.id}.wav",
            license="ElevenLabs output",
        )
        for fx in song.effects
    ]
    return lines, effects


def main(song: Song, extra: Callable[[dict[str, float]], dict] = lambda starts: {}) -> int:
    """Resolve, check, place and mix ``song`` into ``PROJECT/dialogue.json``. ``extra`` adds episode fields from the
    effects' start times, by id."""
    parser = argparse.ArgumentParser(description=f"{song.title}: sung lines, effects and the groove")
    parser.add_argument("project", type=Path)
    parser.add_argument("--key-stdin", action="store_true", help="read the ElevenLabs key from standard input")
    parser.add_argument(
        "--engine", type=Path, default=os.environ.get("SRSTUDIO_ENGINE") or shutil.which("scene-render")
    )
    args = parser.parse_args()
    os.umask(0o077)  # generated outputs are private: folders 700, files 600
    if args.engine is None:
        raise SystemExit("no scene-render engine: pass --engine or set SRSTUDIO_ENGINE")
    root = args.project.resolve()
    assets = root / "assets"
    assets.mkdir(parents=True, exist_ok=True)
    key = sys.stdin.read().strip().strip("'\"") if args.key_stdin else os.environ.get(KEY_ENV, "")
    cache = assets / "elevenlabs"
    groove = song.groove

    # 1. Resolve the lines and effects through the engine; it pins every file it wrote.
    lines, effects = declarations(song)
    document = audio_document(root / f"{song.slug}.audio.scene.xml", [*lines, *effects], sample_rate=RATE)
    env = {CONSENT_ENV: "1", CACHE_ENV: str(cache)}
    if key:
        env[KEY_ENV] = key
    for target in resolve(document, engine=args.engine, env=env):
        print(f"{target.id}: {target.status}")
    pins = pinned(document, [*lines, *effects])

    # 2. Every line must be heard as written.
    client = ElevenLabsClient(cache, key="")
    heard, failures = [], []
    for line, item in zip(song.lines, lines, strict=True):
        transcript = client.transcribe(pins[item.id].path)
        heard.append({"role": line.role, "expected": line.text, "heard": transcript.text})
        try:
            check_transcript(transcript, line.text)
        except TranscriptMismatch as exc:
            failures.append(str(exc))
    (root / "voice-transcript.json").write_text(
        json.dumps({"recognizer": f"ElevenLabs {STT_MODEL}", "lines": heard, "passed": not failures}, indent=2) + "\n"
    )
    if failures:
        raise SystemExit("speech check failed:\n" + "\n".join(failures))

    # 3. Place each line on its beat; it must end before the next line starts.
    trims = [trim_speech(pins[item.id].path) for item in lines]
    voice_gain = gain_to_peak(max(t.peak for t in trims), VOICE_PEAK)
    starts = [groove.at(*line.at) for line in song.lines]
    phrases, clips = [], []
    for i, (line, item, trim) in enumerate(zip(song.lines, lines, trims, strict=True)):
        start, end = starts[i], starts[i] + trim.clip_out - trim.clip_in
        limit = starts[i + 1] if i + 1 < len(starts) else song.lines_end
        if end > limit - 0.05:
            raise SystemExit(f"line {i + 1} {line.text!r} runs to {end:.3f}s, past {limit - 0.05:.3f}s: speed it up")
        voice = song.voices[line.role]
        phrases.append(
            {
                "role": line.role,
                "text": line.text,
                "caption": line.caption,
                "voice": voice.id,
                "voice_name": voice.name,
                "speed": line.speed,
                "start": round(start, 6),
                "end": round(end, 6),
                "trim_seconds": trim.clip_in,
            }
        )
        place = Placement(
            start=round(start, 6),
            clip_in=trim.clip_in,
            clip_out=trim.clip_out,
            gain_db=round(voice_gain, 4),
            role="dialogue",
            language="en",
        )
        clips.append(PlacedClip(item, pins[item.id].sha256, place))
        print(f"{start:6.3f}-{end:6.3f}  {line.role}: {line.text}")

    sound_effects, effect_starts = [], {}
    for spec, item in zip(song.effects, effects, strict=True):
        fx = trim_effect(pins[item.id].path, longest=spec.longest)
        at = round(groove.at(*spec.at) - spec.early, 6)
        clips.append(
            PlacedClip(
                item,
                pins[item.id].sha256,
                Placement(
                    start=at,
                    clip_in=fx.clip_in,
                    clip_out=fx.clip_out,
                    gain_db=round(gain_to_peak(fx.peak, spec.peak), 4),
                    fade_in=0.005,
                    fade_out=0.06,
                    role="effects",
                ),
            )
        )
        sound_effects.append({"name": item.id, "start": at, "duration": round(fx.clip_out - fx.clip_in, 6)})
        effect_starts[item.id] = at

    # 4. The groove, from the same grid.
    music = render(groove, song.sections, rate=RATE, seed=song.seed, peak=MUSIC_PEAK, tail=TAIL)
    write_wav(assets / "groove.wav", music, RATE)
    duration = math.ceil(len(music) / RATE * FPS) / FPS

    # 5. The caption face: the Soft style's Google Font, fetched once, verified and pinned in fonts.lock.json.
    if SOFT.font.google is None:
        raise SystemExit("the Soft style names no Google Font for its captions")
    try:
        face = fonts.install(SOFT.font.google, assets / "fonts")
    except fonts.FontError as exc:
        raise SystemExit(f"caption font: {exc}") from exc
    print(f"font {face.family} {face.weight} {face.license} sha256 {face.sha256}")

    timeline = {
        "title": song.title,
        "language": "en-US",
        "tts_engine": "ElevenLabs",
        "model": MODEL,
        "voice_note": song.voice_note,
        "duration": duration,
        "bpm": groove.bpm,
        "phrases": phrases,
        "sound_effects": sound_effects,
        "clips": [c.to_dict() for c in clips],
        **extra(effect_starts),
    }
    (root / "dialogue.json").write_text(json.dumps(timeline, indent=2) + "\n")
    print(f"duration {duration:.3f}s at {groove.bpm:g} bpm")
    return 0
